import type { ContestReplayImportMapItem } from "@/types/contest.ts";
import { GetText } from "@/text/library.ts";

// 榜单回放行的身份与展示辅助（收藏键、首 AC 高亮、tiebreak 排序与徽标 tooltip 共用）。
//
// 行键口径与后端 RankKey 一致：回放行 `replay:<replayId>:<sourceUserId>`，真人行 `user:<userId>`；
// 同一用户既在本场真人榜又出现在回放中时，两行键不冲突，避免收藏 / 高亮串号。
// 数据来源只有榜单 rank 链路一处，抽成纯函数是为了可测——键格式写错类型系统不会报错兜住。

/** 回放行身份相关字段的最小结构（原始行 ContestRank 与视图行 ContestRankView 都可传入） */
export interface ReplayRankIdentityRow {
  /** 视图行用户 ID（回放行保留 source_user_id 兜底） */
  userId?: number;
  /** 原始行提交者 ID */
  inserter?: number;
  /** 是否回放行 */
  isReplay?: boolean;
  /** 回放关联 ID */
  replayId?: number;
  /** 源比赛选手 ID */
  sourceUserId?: number;
  /** 源比赛标题 */
  sourceTitle?: string;
  /** 后端下发的复合行键（已下发时直接采用） */
  rankKey?: string;
}

/** 判定是否回放行：仅 isReplay === true 视为回放，旧响应缺字段时按真人行处理 */
export function isReplayRow(row: ReplayRankIdentityRow): boolean {
  return row?.isReplay === true;
}

/** 取行身份的兜底用户 ID：userId 优先，其次 inserter */
function resolveUserId(row: ReplayRankIdentityRow): number {
  return row.userId ?? row.inserter ?? 0;
}

/**
 * 生成行身份键：
 * - 回放行：后端已下发 rank_key 时直接采用，否则按 `replay:<replayId>:<sourceUserId>` 合成；
 * - 真人行：`user:<userId>`。
 */
export function replayRankKey(row: ReplayRankIdentityRow): string {
  if (isReplayRow(row)) {
    if (row.rankKey) {
      return row.rankKey;
    }
    const replayId = row.replayId ?? 0;
    const sourceUserId = row.sourceUserId ?? resolveUserId(row);
    return `replay:${replayId}:${sourceUserId}`;
  }
  return `user:${resolveUserId(row)}`;
}

/**
 * 同 solved / penalty 下的 tiebreak 比较器（可直接传入 Array.prototype.sort）：
 * - 两行均为真人：按 userId 数值升序，保持历史行为，避免 `user:100` 按字典序排在 `user:9` 之前；
 * - 至少一行为回放：退化为行身份键字符串升序（回放复合键与真人 `user:` 键分开排序，结果确定性）。
 */
export function replayRankTiebreak(a: ReplayRankIdentityRow, b: ReplayRankIdentityRow): number {
  if (!isReplayRow(a) && !isReplayRow(b)) {
    const idA = resolveUserId(a);
    const idB = resolveUserId(b);
    return idA - idB;
  }
  const keyA = replayRankKey(a);
  const keyB = replayRankKey(b);
  return keyA < keyB ? -1 : keyA > keyB ? 1 : 0;
}

/**
 * 回放行来源 tooltip 文案：拼接源比赛标题；无源标题时退化为「回放」占位；
 * 真人行返回空串（不展示回放来源 tooltip）。
 */
export function formatReplaySourceTooltip(row: ReplayRankIdentityRow): string {
  if (!isReplayRow(row)) {
    return "";
  }
  const sourceTitle = (row.sourceTitle ?? "").trim();
  if (!sourceTitle) {
    return "回放";
  }
  return `回放自：${sourceTitle}`;
}

// ---------- 编辑页回放关联 Tab：候选与匹配状态展示辅助 ----------

/** 可关联候选条目最小结构（原始候选与 camelCase 视图都可传入） */
export interface EligibleCandidate {
  /** 候选源比赛标题 */
  title: string;
  /** 候选开始时间（已本地化展示串，可选） */
  startTime?: string;
  /** 候选结束时间（已本地化展示串，可选） */
  endTime?: string;
  /** 是否已与本场关联 */
  linked?: boolean;
  /** 中立本体是否与本场已关联回放完全相同（别名候选） */
  isAlias?: boolean;
}

/** 题目匹配状态文案：✓ 题目匹配 / ✗ 题目不一致；编辑页关联列表与榜单面板漂移提示共用口径 */
export function formatReplayProblemMatched(matched: boolean): string {
  return matched ? "✓ 题目匹配" : "✗ 题目不一致";
}

/** 候选是否已关联：已关联候选在选择器中置灰禁用，不允许重复关联 */
export function isEligibleLinked(candidate: Pick<EligibleCandidate, "linked">): boolean {
  return candidate?.linked === true;
}

/** 候选选择器选项文案：标题 + 起止时间区间；已关联项追加「已关联」标注 */
export function formatEligibleOptionLabel(candidate: EligibleCandidate): string {
  const range = [candidate.startTime, candidate.endTime].filter(Boolean).join(" ~ ");
  const text = range ? `${candidate.title}（${range}）` : candidate.title;
  return isEligibleLinked(candidate) ? `${text}（已关联）` : text;
}

/** 别名候选创建前的确认提示文案：中立本体与本场已关联回放完全相同，将作为别名展示 */
export const REPLAY_ALIAS_CONFIRM_TEXT = "榜单完全相同，将作为别名展示";

// ---------- 榜单文件导入：题目映射与示例 CSV ----------

/** 题目序号（1 起）转字母编号：1→A，26→Z，27→AA，与比赛题目题号口径一致 */
export function contestProblemLabel(index: number): string {
  let result = "";
  let n = index;
  while (n > 0) {
    n--;
    result = String.fromCharCode(65 + (n % 26)) + result;
    n = Math.floor(n / 26);
  }
  return result;
}

/** 默认题目映射：源题目顺序 ↔ 目标比赛题目顺序（A→第 1 题）。返回源序号与目标序号对。 */
export function defaultImportMapping(sourceCount: number, targetCount: number): ContestReplayImportMapItem[] {
  const items: ContestReplayImportMapItem[] = [];
  const common = Math.min(sourceCount, targetCount);
  for (let i = 0; i < common; i++) {
    items.push({ sourceIndex: i, targetIndex: i + 1 });
  }
  return items;
}

/** 示例榜单 CSV 样例行的题目格：AC / 未 AC / 未提交循环排列 */
const SAMPLE_CELLS = ["+12:34", "-2", "."] as const;

/** UTF-8 BOM：让 Excel 打开 CSV 时正确识别中文编码 */
const UTF8_BOM = "\uFEFF";

/**
 * 生成示例榜单 CSV 文本（含 BOM 供 Excel 正确识别中文）。
 * 题目列按本场题目数生成 A/B/C…，附三行可直接改写的样例选手。
 */
export function buildSampleReplayCsv(problemCount: number): string {
  const problemHeader = Array.from({ length: problemCount }, (_, i) => contestProblemLabel(i + 1)).join(",");
  const lines = [
    "# 榜单回放示例：列顺序固定为 Rank,Handle,Nickname,题目列（A,B,C…，与本场题目一一对应）",
    "# 题目格写法：+mm:ss 表示 AC（相对比赛开始的时刻）；-k 表示未 AC（k 次尝试）；. 或空表示未提交",
    `Rank,Handle,Nickname,${problemHeader}`,
  ];

  const sampleRows: Array<[string, string]> = [
    ["alice", "爱丽丝"],
    ["bob", "鲍勃"],
    ["carol", "卡罗尔"],
  ];
  sampleRows.forEach(([handle, nickname], rowIdx) => {
    const cells = Array.from({ length: problemCount }, (_, colIdx) => SAMPLE_CELLS[(rowIdx + colIdx) % SAMPLE_CELLS.length]);
    lines.push(`${rowIdx + 1},${handle},${nickname},${cells.join(",")}`);
  });

  return UTF8_BOM + lines.join("\r\n") + "\r\n";
}

// ---------- 创建页回放暂存：暂存结构、判定与落库失败文案 ----------
//
// 创建页（contestId === 0）没有比赛 ID，源比赛关联与榜单文件导入都只能先暂存在前端，
// 等「创建」成功拿到新比赛 ID 后再逐条落库。判定与文案都是纯逻辑，抽出来是为了可测：
// 置灰判定写错会让同一候选重复暂存，别名判定写错会把两个不同榜单静默合并。

/** 创建页暂存的源比赛回放关联（创建成功后逐条落库） */
export interface PendingReplaySource {
  contestId: number;
  title: string;
  bodyHash?: string;
}

/** 创建页暂存的榜单文件导入 */
export interface PendingReplayImport {
  previewId: string;
  title: string;
  problemMap: ContestReplayImportMapItem[];
  playerCount: number;
  sourceProblemCount: number;
}

/** 候选是否已暂存（创建期选择器置灰，与编辑态 linked 并列） */
export function isPendingSourceStaged(pending: PendingReplaySource[], contestId: number): boolean {
  if (!Array.isArray(pending)) {
    return false;
  }
  return pending.some((item) => item.contestId === contestId);
}

/**
 * 暂存项中是否已有相同本体指纹（创建期别名判定）。
 * bodyHash 为空一律不算重复：缺省指纹无法证明与本场已有回放同源，
 * 宁可多落一条关联，也不能把两个不同榜单静默合并成别名。
 */
export function hasPendingAliasBodyHash(pending: PendingReplaySource[], bodyHash?: string): boolean {
  if (!bodyHash) {
    return false;
  }
  if (!Array.isArray(pending)) {
    return false;
  }
  return pending.some((item) => item.bodyHash === bodyHash);
}

/** 落库失败明细（label 为回放展示名，code 为后端错误码） */
export interface ReplayApplyFailure {
  label: string;
  code: number | string;
}

/** 失败明细 → 可直接展示的文案行（错误码走 text/library 的 GetText，未登记码回落为错误码） */
export function formatReplayApplyFailures(failures: ReplayApplyFailure[]): string[] {
  if (!Array.isArray(failures)) {
    return [];
  }
  return failures.map((failure) => {
    const [found, text] = GetText(failure.code);
    const reason = found ? text : String(failure.code);
    return `「${failure.label}」关联失败：${reason}`;
  });
}

